input.content:
:root {
  --ink: #1d1d1f;
  --ink-soft: #5c5c63;
  --surface: #fff;
  --page: #f6f6f7;
  --line: #d9d9de;
  --line-soft: #ececf0;
  --accent: #0a58ca;
  --accent-ink: #fff;
  --danger: #b00020;
  --warn: #7a4f00;
  --focus: #0a58ca;
  --radius: 8px;
  font-family: system-ui, sans-serif;
  line-height: 1.5;
  color: var(--ink);
  background: var(--page);
  color-scheme: light;
}
body { margin: 0; }
::selection { background: #cfe0fb; color: var(--ink); }
:focus-visible { outline: 2px solid var(--focus); outline-offset: 2px; }

header { display: flex; justify-content: space-between; align-items: center; gap: 1rem; padding: 0.75rem 1.5rem; background: var(--surface); border-bottom: 1px solid var(--line); }
.brand { font-weight: 600; color: inherit; text-decoration: none; }
.brand:hover { text-decoration: underline; text-underline-offset: 3px; }
main { max-width: 64rem; margin: 0 auto; padding: 1.5rem; }

section, .card { background: var(--surface); border: 1px solid var(--line); border-radius: var(--radius); padding: 1.25rem; margin-bottom: 1rem; }
h2 { font-size: 1.1rem; line-height: 1.3; margin: 0 0 0.75rem; text-wrap: balance; }
p { margin: 0 0 0.75rem; max-width: 70ch; }
section > :last-child { margin-bottom: 0; }

label { display: block; font-weight: 500; margin: 1rem 0 0.25rem; }
textarea, input[type='text'], input[type='url'], input[type='password'] {
  width: 100%; box-sizing: border-box; font: inherit; padding: 0.5rem 0.6rem;
  color: inherit; background: var(--surface); border: 1px solid #8e8e96; border-radius: 6px;
}
textarea { resize: vertical; }
textarea:focus-visible, input:focus-visible { outline-offset: 0; border-color: var(--focus); }
textarea[readonly], input[readonly] { background: var(--page); border-color: var(--line); }
::placeholder { color: #6f6f77; opacity: 1; }

button {
  font: inherit; padding: 0.45rem 1rem; margin: 0 0.5rem 0.25rem 0; cursor: pointer;
  color: var(--ink); background: var(--surface); border: 1px solid #8e8e96; border-radius: 6px;
}
button:hover:not(:disabled) { background: var(--page); border-color: var(--ink-soft); }
button:active:not(:disabled) { background: var(--line-soft); }
button:disabled { cursor: not-allowed; opacity: 0.55; }
button.primary { background: var(--accent); border-color: var(--accent); color: var(--accent-ink); font-weight: 600; }
button.primary:hover:not(:disabled) { background: #0847a3; border-color: #0847a3; }
button.danger { color: var(--danger); border-color: var(--danger); }
button.danger:hover:not(:disabled) { background: #fdecef; border-color: var(--danger); }
button.link { background: none; border: none; color: var(--accent); padding: 0.25rem 0; margin: 0; text-decoration: underline; text-underline-offset: 3px; }
button.link:hover:not(:disabled) { background: none; }

.muted { color: var(--ink-soft); font-size: 0.9rem; }
.error { color: var(--danger); }
.notice { background: #fff4e5; border: 1px solid #e0a655; color: #4d3200; padding: 0.75rem 1rem; border-radius: var(--radius); margin-bottom: 1rem; }
.provisional { border-style: dashed; }
.issues { margin: 0.25rem 0 0.5rem; padding-left: 1.2rem; color: var(--danger); }
.issues.warn { color: var(--warn); }
code { font-family: ui-monospace, SFMono-Regular, Menlo, monospace; font-size: 0.88em; }
pre { background: #f3f3f5; padding: 0.75rem; border-radius: 6px; overflow-x: auto; font-size: 0.85rem; }
details > summary { cursor: pointer; margin: 0.25rem 0; }

table { border-collapse: collapse; width: 100%; font-size: 0.9rem; font-variant-numeric: tabular-nums; }
th, td { text-align: left; padding: 0.4rem 0.6rem; border-bottom: 1px solid var(--line-soft); vertical-align: top; }
th { font-weight: 600; color: var(--ink-soft); white-space: nowrap; }
.table-scroll { overflow-x: auto; }

.bar { display: flex; height: 0.9rem; background: var(--line-soft); border-radius: 4px; overflow: hidden; margin: 0.25rem 0 0.5rem; }
.bar span { display: block; height: 100%; }
.compare { display: grid; grid-template-columns: 1fr 1fr; gap: 1rem; margin-top: 0.75rem; }

@media (max-width: 40rem) {
  header { padding: 0.75rem 1rem; }
  main { padding: 1rem; }
  section, .card { padding: 1rem; }
  .compare { grid-template-columns: 1fr; }
  button { min-height: 2.75rem; }
}
@media (prefers-reduced-motion: no-preference) {
  button { transition: background-color 0.15s ease-out, border-color 0.15s ease-out; }
}

