import { createApp } from 'vue'
import { createRouter, createWebHistory } from 'vue-router'
import App from './App.vue'
import CampaignView from './views/CampaignView.vue'
import ComposeView from './views/ComposeView.vue'
import './style.css'

const router = createRouter({
  history: createWebHistory(),
  routes: [
    { path: '/', component: ComposeView },
    { path: '/campaigns/:id', component: CampaignView, props: true },
  ],
})

createApp(App).use(router).mount('#app')
import { ref } from 'vue'
import { createApi } from './api/client'

const key = 'scc.token'

function load(): string | null {
  try {
    return sessionStorage.getItem(key)
  } catch {
    return null
  }
}

export const token = ref<string | null>(load())

export function setToken(t: string) {
  token.value = t
  try {
    sessionStorage.setItem(key, t)
  } catch {
    // Depolama kapalıysa anahtar yalnız bu sayfada kalır.
  }
}

export function clearToken() {
  token.value = null
  try {
    sessionStorage.removeItem(key)
  } catch {
  }
}

export const api = createApi({ token: () => token.value, onUnauthorized: clearToken })
